# Salinan tetap aturan poin usaha saat migrasi ini dibuat (operasi.services).
BASE_POINTS = {"taman_buru": 10, "komsos": 6, "pemetaan": 8, "temuan_ilegal": 8}


def backfill_effort_points(apps, schema_editor):
    """Isi poin usaha laporan lama agar KPI tidak turun setelah pembaruan."""
    Activity = apps.get_model("operasi", "Activity")
    ActivityWeight = apps.get_model("operasi", "ActivityWeight")
    weights = dict(ActivityWeight.objects.values_list("activity_type", "points"))
    for activity in Activity.objects.annotate(
        n_photos=models.Count("photos", distinct=True)
    ).iterator(chunk_size=500):
        kind = activity.activity_type
        points = Decimal(weights.get(kind, BASE_POINTS.get(kind, 4)))
        if activity.n_photos:
            points += min(Decimal("0.5") * activity.n_photos, Decimal("3"))
        narrative = len((activity.description or "").strip()) + len(
            (activity.outcome or "").strip()
        )
        if narrative >= 100:
            points += 2
        if activity.location is not None:
            points += 1
        Activity.objects.filter(pk=activity.pk).update(
            effort_points=points.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)
        )


